window.SaveNewAddress = async function (card) { if (!card) { alert('No card passed'); return; } const label = document.getElementById('AMNAL')?.value.trim(); const searchJSON = document.getElementById('AMHJSON')?.value; const typeID = document.getElementById('AMNATID')?.value; const modalId = document.querySelector('.AddressModalId')?.value; if (!label || !searchJSON || !typeID) { alert('Validation failed: Missing Label, Address or Address Type'); return; } toggleGlobalSpinner(true); try { const resp = await fetch('/User/Address/EndPoints/AddAddress', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ModalId: modalId, Label: label, AddressJSON: searchJSON, TypeID: parseInt(typeID) }) }); if (!resp.ok) { let errMsg = 'Server returned an error'; try { const errData = await resp.json(); errMsg = errData?.msg || errMsg; } catch {} throw new Error(errMsg); } const data = await resp.json(); if (!data?.ok) throw new Error(data?.msg || 'Failed to save new address'); AddNewAddressCard(data); CloseNewAddressCard(); } catch(err) { alert('ERROR: ' + (err.message || 'Unknown error')); } finally { toggleGlobalSpinner(false); } };
window.SaveNewAddressFlexible = async function(element) { if (!element) { alert('No element passed'); return; } const modal = element.closest('.custom-modal'); if (!modal) { alert('No modal found'); return; } const modalId = modal.getAttribute('data-modal-id'); const card = modal.querySelector('.new-address-card'); if (!card) { alert('No card found'); return; } const labelEl = card.querySelector('.new-address-label'); const addressEl = card.querySelector('.location-payload'); const typeEl = card.querySelector('.new-address-type'); if (!labelEl || !addressEl || !typeEl) { alert('Validation failed: missing field data.'); return; } toggleGlobalSpinner(true); try { const resp = await fetch('/User/Address/EndPoints/AddAddress', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ModalId: modalId, Label: labelEl.value, AddressJSON: addressEl.value, TypeID: parseInt(typeEl.value) }) }); if (!resp.ok) throw new Error('Server error'); const data = await resp.json(); AddNewAddressCard(data); const lastResp = await fetch('/User/Address/EndPoints/GetLastAddress', { method: 'POST' }); if(lastResp.ok) { const lastData = await lastResp.json(); if(lastData.ok) { const id = lastData.id; const label = lastData.label; const address = lastData.address; const allSelects = [document.getElementById('PIUPAID'), document.getElementById('PIUUDAID')]; allSelects.forEach(sel => { if(sel) { let opt = Array.from(sel.options).find(o => o.value == id); if(!opt) { opt = document.createElement('option'); opt.value = id; opt.textContent = `${label} — ${address}`; sel.appendChild(opt); } } }); let nearestSelect = null; let parent = element; while(parent && !nearestSelect) { nearestSelect = parent.querySelector('select.location'); parent = parent.parentElement; } if(nearestSelect) { nearestSelect.value = id; nearestSelect.dispatchEvent(new Event('change')); } else { console.log('No nearest select with .location found'); } } else { alert('Internal Error: missing lastData'); } } else { alert('Unexpected server response from GetLastAddress'); } } catch(err) { alert('ERROR: ' + (err.message || 'Unknown error')); } finally { toggleGlobalSpinner(false); } }; 
window.DeleteAddressCard = async function (button) { if (!button) return; const card = button.closest('.address-card'); if (!card) return; const radio = card.querySelector('.address-radio'); if (!radio) return; const addressId = parseInt(radio.value, 10); const label = card.querySelector('.address-label')?.textContent?.trim() || 'this address'; if (!window.confirm(`Are you sure you want to delete "${label}"?`)) { card.scrollIntoView({ behavior: 'smooth', block: 'center' }); radio.focus(); return; } toggleGlobalSpinner(true); try { const response = await fetch('/User/Address/EndPoints/DeleteSelected', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ Id: addressId }) }); const data = await response.json(); if (!data?.ok) throw new Error(data?.msg || 'Failed to delete address.'); card.remove(); } catch (err) { console.error(err); alert(err.message || 'Error deleting address.'); } finally { toggleGlobalSpinner(false); } } 
window.AddNewAddressCard = function (data) { if (!data || !data.newcard) return; const modal = document.querySelector('.custom-modal[data-modal-type="address"]'); if (!modal) return; const container = modal.querySelector('.custom-modal-body'); if (!container) return; const temp = document.createElement('div'); temp.innerHTML = data.newcard.trim(); const newCard = temp.firstElementChild; if (!newCard) return; const addSection = container.querySelector('.mt-3'); if (addSection) { container.insertBefore(newCard, addSection); } else { container.appendChild(newCard); } newCard.style.opacity = 0; newCard.style.transform = 'translateY(-10px)'; newCard.style.transition = 'opacity 0.5s ease, transform 0.5s ease'; if (newCard.style.display === 'none') { newCard.style.display = ''; } requestAnimationFrame(() => { newCard.style.opacity = 1; newCard.style.transform = 'translateY(0)'; }); container.scrollTo({ top: newCard.offsetTop, behavior: 'smooth' }); } 
window.toggleAddressType = function (isKnown, knownTypeId = null, inputId = null) { if (!inputId) { return; }  const input = document.getElementById(inputId);  if (!input) { return; }  const container = input.closest('.address-card')?.querySelector('.address-type-container');  if (!container) { return; }  const select = container.querySelector('select');  if (!select) { return; }  if (!input.value.trim()) {  container.style.display = 'none';  select.value = '';  } else if (isKnown) {  container.style.display = 'none';  if (knownTypeId) select.value = knownTypeId;  } else {  container.style.display = 'block';  select.value = '';  } };function showAddressCard(cardId, modalType) { const card = document.getElementById(cardId); if (!card) return; const modal = document.querySelector(`.custom-modal[data-modal-type='${modalType}']`); let el = card; while(el && el !== document.body && el !== modal) { const style = window.getComputedStyle(el); if(style.display === 'none') el.style.display = 'block'; el = el.parentElement; } card.style.display = 'block'; const input = card.querySelector('.new-address-label'); if(input) input.focus(); card.scrollIntoView({ behavior:'smooth', block:'center' }); } 
