window.ResetLocationModalInputs = function () { const type = document.getElementById('locationAddressTypeId'); const preview = document.getElementById('locationPreview'); const payload = document.getElementById('locationPayload'); if (type) type.selectedIndex = 0; if (preview) preview.textContent = '(not loaded yet)'; if (payload) payload.value = ''; const errEl = document.getElementById('locationTypeError'); if (errEl) errEl.textContent = ''; } 
window.ResolveCurrentLocation = function () { document.getElementById('LMSBTN').style.display = 'none'; const preview = document.getElementById('locationPreview'); if (!('geolocation' in navigator)) { if (preview) preview.textContent = 'Location not supported.'; return; } if (preview) preview.textContent = 'Getting location…'; const tryGeolocation = (highAccuracy, retries = 3) => { navigator.geolocation.getCurrentPosition( (pos) => { const { latitude: lat, longitude: lon, accuracy } = pos.coords; if (highAccuracy && accuracy > 15 && retries > 0) { if (preview) preview.textContent = `Accuracy low(${Math.round(accuracy)} m), retrying…`; setTimeout(() => tryGeolocation(true, retries - 1), 1000); return; } GetAddressFromCoords(lat, lon); }, (err) => { if (highAccuracy) { if (preview) preview.textContent = 'High-accuracy failed, trying low-accuracy…'; tryGeolocation(false, 1); } else { if (preview) preview.textContent = 'Unable to get location. Please enter manually.'; } }, { enableHighAccuracy: highAccuracy, timeout: highAccuracy ? 10000 : 5000, maximumAge: 0 }); }; tryGeolocation(true, 3); }
window.ValidateLocationModal = function () { const type = document.getElementById('LMATID'); const payload = document.getElementById('locationPayload'); const errEl = document.getElementById('locationTypeError'); if (!type || !payload) return false; let valid = true; if (type.selectedIndex === 0) { if (errEl) errEl.textContent = 'Please select an address type.'; valid = false; } else { if (errEl) errEl.textContent = ''; } if (!payload.value) { alert('No address data found. Please resolve your location first.'); valid = false; } return valid; }; 
window.SaveLocation = async function () {const preview = document.getElementById('locationPreview'); const typeSelect = document.getElementById('LMATID'); const payloadEl = document.getElementById('locationPayload'); if (!typeSelect?.value) { alert('Please select an address type.'); return; } if (!preview || preview.textContent === '(not loaded yet)') { alert('Preview not ready'); return; } if (!payloadEl?.value) { alert('No location to save.'); return; } const addressData = JSON.parse(payloadEl.value); const typeID = parseInt(typeSelect.value, 10); toggleGlobalSpinner(true); try { const resp = await fetch('/User/Address/EndPoints/AddFromLocation', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ AddressTypeID: typeID, JSonpayload: JSON.stringify(addressData) }) }); let text = await resp.text(); let data = {}; try { data = JSON.parse(text); } catch(e) { alert('Save JSON parse failed: ' + e.message); throw e; } if (!data?.ok && !data?.success) throw new Error(data?.message || 'Save failed.'); const toggle = document.getElementById('addressToggle'); const label = (data.label || preview.textContent || '').trim(); if (!toggle) alert('No address toggle found.'); if (!label) alert('No label found.'); if (toggle && label) { toggle.innerHTML = `<i class="fa-solid fa-home"></i>${label}&nbsp;<i class="fa-solid fa-chevron-down dropdown-icon"></i>`; } if (data.addressId) { const modal = document.querySelector('.custom-modal[data-modal-type="address"]'); const modalId = modal?.getAttribute('data-modal-id') || ''; try { const cardResp = await fetch('/User/Address/EndPoints/BuildCard', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ModalId: modalId, UserAddressId: data.addressId, SetDefault: true }) }); const cardText = await cardResp.text(); let cardData = {}; try { cardData = JSON.parse(cardText); } catch(e) { alert('BuildCard JSON parse failed: ' + e.message); throw e; } if (cardData?.ok && cardData?.newcard) { AddNewAddressCard(cardData); } } catch (err) { alert('BuildCard failed: ' + err.message); } finally { const closeBtn = document.getElementById('LMBTNCLS'); if (closeBtn) closeBtn.click(); } } else { const closeBtn = document.getElementById('LMBTNCLS'); if (closeBtn) closeBtn.click(); } } catch (err) { alert('SaveLocation failed: ' + err.message); if (preview) preview.textContent = err?.message || 'Save failed.'; } finally { toggleGlobalSpinner(false); ResetLocationModalInputs(); const closeBtn = document.getElementById('LMBTNCLS'); if (closeBtn) closeBtn.click(); } };
window.GetAddressFromCoords = function (lat, lon) { const preview = document.getElementById('locationPreview'); const payload = document.getElementById('locationPayload'); const token = document.querySelector('meta[name="t"]')?.content?.trim(); if (!token) { if (preview) preview.textContent = 'Mapbox token missing.'; return; } if (!Number.isFinite(lat) || !Number.isFinite(lon)) { if (preview) preview.textContent = 'Invalid coordinates.'; return; } if (preview) preview.textContent = 'Resolving address…'; const url = `https://api.mapbox.com/geocoding/v5/mapbox.places/${lon},${lat}.json?types=address&limit=1&country=nz&access_token=${encodeURIComponent(token)}`; fetch(url) .then(res => res.json()) .then(data => { const feature = data?.features?.[0] || null; if (!feature) throw new Error('No address found for this location.'); const label = (feature.place_name || feature.text || '').trim(); if (preview) preview.textContent = label; if (payload) payload.value = JSON.stringify({ latitude: lat, longitude: lon, feature: feature }); document.getElementById('LMSBTN').style.display = 'inline-block'; }) .catch(err => { if (preview) preview.textContent = err?.message || 'Unable to resolve address.'; document.getElementById('LMSBTN').style.display = 'none'; }); } 
