window.PIUaddTask = function () { const check = PIUvalidateTaskInputs(); if (check === 'invalid') { return false; } if (check === 'empty') { return true; } const task = { recipient: document.getElementById('Recipient')?.value.trim() || '', reference: document.getElementById('PIUR')?.value.trim() || '', pickupAddressId: document.getElementById('PIUPAID')?.value || '', dropoffAddressId: document.getElementById('PIUUDAID')?.value || '', packageTypeId: document.getElementById('PIUPTID')?.value || '', packageSizeId: document.getElementById('PIUPSID')?.value || '', readyTime: document.getElementById('PIURT')?.value || '', specificTime: document.getElementById('PIUST')?.value || '', pickupNotes: document.getElementById('PIUPN')?.value.trim() || '', dropoffNotes: document.getElementById('PIUDN')?.value.trim() || '', dropoffTypeId: document.getElementById('PIUDTID')?.value || '' }; if (task.pickupAddressId === task.dropoffAddressId) { alert('Pickup and Drop-off addresses cannot be the same.'); return false; } window.taskList.push(task); document.getElementById('TaskData').value = JSON.stringify(window.taskList); PIUrenderTaskList(); PIUresetInput(); return true; }
window.PIUrenderTaskList = async function() { const card = document.getElementById('CardTaskList'); if (!card) return; const container = card.querySelector('.tasklist'); if (!container) return; container.innerHTML = ''; if (window.taskList.length === 0) { card.style.display = 'none'; container.style.display = 'none'; document.getElementById('CardTaskListTitle').innerHTML = "Tasks"; document.getElementById('CreateTasks').style.display = 'block'; return; } card.style.setProperty('display','flex','important'); container.style.display = 'flex'; container.style.flexDirection = 'column'; container.style.gap = '0.5rem'; for (let i = 0; i < window.taskList.length; i++) { const t = window.taskList[i]; try {const response = await fetch(`/Home/PickitUp/Endpoints/TaskCard?index=${i}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(t) }); if (!response.ok) { container.innerHTML += `<div style="color:red;"> Failed to load task #${i+1}</div>`; continue; } const html = await response.text(); container.innerHTML += html; } catch (err) { console.error('Error fetching task card:', err); container.innerHTML +=`<div style="color:red;">Error loading task #${i+1}</div>`; } } } 
