window.PIUonAllSetClick = async function () { const taskcheck = PIUaddTask(); if (taskcheck === false) return; if (window.taskList.length === 0) { PIUrenderTaskList(); return; } window.PIUpricingData = null; const CardTaskListTitle = document.getElementById('CardTaskListTitle'); const CreateTasks = document.getElementById('CreateTasks'); const PIUConfirm = document.getElementById('PIUConfirm'); const PIUCancel = document.getElementById('PIUCancel'); const PIUStatus = document.getElementById('PIUStatus'); const PIUStatusText = document.getElementById('PIUStatusText'); CardTaskListTitle.innerText = 'Confirm Tasks'; CreateTasks.style.display = 'none'; PIUCancel.style.display = 'inline-block'; PIUConfirm.style.display = 'inline-block'; PIUStatus.style.display = 'inline-block'; PIUStatusText.innerText = 'Fetching price for tasks...'; try { const response = await fetch('/Home/PickitUp/Endpoints/CalculatePricing', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(window.taskList) }); if (!response.ok) throw new Error('Failed to fetch pricing'); const pricingData = await response.json(); if (!pricingData.tasks || pricingData.tasks.length === 0) { alert('No pricing returned for tasks.'); return; }PIUupdatePricing(pricingData); const container = document.querySelector('.tasklist'); let footer = document.getElementById('OrderTotalFooter'); if (!footer) { footer = document.createElement('div'); footer.id = 'OrderTotalFooter'; footer.className = 'order-total-footer'; footer.style.textAlign = 'right'; footer.style.fontWeight = 'bold'; container.after(footer); } document.getElementById('PIUpricingJSON').value = JSON.stringify(pricingData); footer.innerHTML = `Service fee: $${pricingData.serviceFee.toFixed(2)}<br />Total: $${pricingData.total.toFixed(2)}`; PIUConfirm.onclick = PIUOPMM; if (pricingData.warning) alert(pricingData.warning); } catch (err) { alert(err); alert('Failed to fetch task pricing. Please try again.'); } finally { PIUStatus.style.display = 'none'; } };
window.PIUvalidateTaskInputs = function () { let anyFilled = false; const recipient = document.getElementById('Recipient')?.value.trim() || ''; if (recipient === '') return 'invalid'; const reference = document.getElementById('PIUR')?.value.trim() || ''; if (reference !== '') { anyFilled = true; } const pickup = document.getElementById('PIUPAID')?.value || ''; if (pickup !== '' && pickup !== '--Select Pickup Address--') { anyFilled = true; } const dropoff = document.getElementById('PIUUDAID')?.value || ''; if (dropoff !== '' && dropoff !== '--Select Dropoff Address--') { anyFilled = true; } const packageType = document.getElementById('PIUPTID')?.value || ''; if (packageType !== '') { anyFilled = true; } const packageSize = document.getElementById('PIUPSID')?.value || ''; if (packageSize !== '') { anyFilled = true; } const readyTime = document.getElementById('PIURT')?.value || ''; if (readyTime !== 'now') { anyFilled = true; } const specificTime = document.getElementById('PIUST')?.value || ''; if (specificTime !== '') { anyFilled = true; } const pickupNotes = document.getElementById('PIUPN')?.value.trim() || ''; if (pickupNotes !== '') { anyFilled = true; } const dropoffNotes = document.getElementById('PIUDN')?.value.trim() || ''; if (dropoffNotes !== '') { anyFilled = true; } const dropoffType = document.getElementById('PIUDTID')?.value || ''; if (dropoffType !== '') { anyFilled = true; } if (!anyFilled) { return 'empty'; } const missingRequired = pickup === '' || pickup === '--Select Pickup Address--' || dropoff === '' || dropoff === '--Select Dropoff Address--' || packageType === '' || packageSize === '' || dropoffType === ''; if (missingRequired) { alert('Please fill in all required fields before continuing.'); return 'invalid'; } return 'valid'; }; 
window.PIUcancelClick = async function () { window.taskList = []; window.taskList.length = 0; window.PIUpricingData = null; const hiddenTaskInput = document.getElementById('TaskData'); if (hiddenTaskInput) hiddenTaskInput.value = '[]'; const cardTaskList = document.getElementById('CardTaskList'); if (cardTaskList) cardTaskList.style.setProperty('display','none','important'); const createTasks = document.getElementById('CreateTasks'); if (createTasks) createTasks.style.display = 'block'; const cancelBtn = document.getElementById('PIUCancel'); if (cancelBtn) cancelBtn.style.display = 'none'; const confirmBtn = document.getElementById('PIUConfirm'); if (confirmBtn) confirmBtn.style.display = 'none'; const PIUStatus = document.getElementById('PIUStatus'); if (PIUStatus) PIUStatus.style.display = 'none'; const title = document.getElementById('CardTaskListTitle'); if (title) title.innerText = 'Tasks'; const pricingHidden = document.getElementById('PIUpricingJSON'); if (pricingHidden) pricingHidden.value = ''; const footer = document.getElementById('OrderTotalFooter'); if (footer) footer.innerHTML = ''; document.querySelectorAll('.PIUPV').forEach(row => row.style.display='none'); PIUresetInput(); if (typeof PIUrenderTaskList === 'function') await PIUrenderTaskList(); } 
window.PIUupdatePricing = function (data) { if (!data.ok) { alert(data.msg || 'Pricing error.'); return; } data.tasks.forEach(task => { const i = task.index; const distanceEl = document.querySelector(`.task-distance[data-index="${i}"]`); const timeEl = document.querySelector(`.task-time[data-index="${i}"]`); const discountEl = document.querySelector(`.task-discount[data-index="${i}"]`); const subtotalEl = document.querySelector(`.task-subtotal[data-index="${i}"]`); if (distanceEl) distanceEl.innerText = (task.distanceMeters / 1000).toFixed(1) + ' km'; if (timeEl) timeEl.innerText = task.travelTimeMinutes + ' min';   if (task.discount && task.discount > 0) {     discountEl.innerText = '-$' + task.discount.toFixed(2);     discountEl.style.display = '';   } else {     const PIUCDID = document.getElementById(`PIUCDID${i}`);     if (PIUCDID) PIUCDID.style.display = 'none';   } if (subtotalEl) subtotalEl.innerText = '$' + task.subtotal.toFixed(2); const pricingRows = distanceEl?.closest('.card')?.querySelectorAll('.PIUPV'); if (pricingRows) pricingRows.forEach(row => row.style.display = ''); }); if (data.warning) alert(data.warning); }; 
